INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6900408, 1039928, 63812, '<td valign="top">nice!</td>', 'nice!', '2012-11-07 03:31:27.000000', NULL, 1),
(6900409, 1039967, 63812, '<td valign="top">beautiful composition!</td>', 'beautiful composition!', '2012-11-07 03:32:46.000000', NULL, 1),
(6900410, 1039978, 63812, '<td valign="top">really nice!</td>', 'really nice!', '2012-11-07 03:33:34.000000', NULL, 1),
(6900688, 1039980, 63218, '<td valign="top">I think the Night Watcher is the crow (or raven). I see windows in the air. All the windows but one have a graceful improvised rope ladder, for escaping through the window. Two of the windows have indoor views, one has a different sky. The girl with the lamp seems to be waiting for someone to escape out that window, down the improvised rope ladder that is moving in a breeze that''s going the other way. The chair in the field, decorated with a red ribbon, a red rose, and a lamp. Sometimes if I describe what I see, I can find the sense of it, but this time no. All the elements look nice together and I like the colors. The girl seems very far away.</td>', 'I think the Night Watcher is the crow (or raven). I see windows in the air. All the windows but one have a graceful improvised rope ladder, for escaping through the window. Two of the windows have indoor views, one has a different sky. The girl with the lamp seems to be waiting for someone to escape out that window, down the improvised rope ladder that is moving in a breeze that''s going the other way. The chair in the field, decorated with a red ribbon, a red rose, and a lamp. Sometimes if I describe what I see, I can find the sense of it, but this time no. All the elements look nice together and I like the colors. The girl seems very far away.', '2012-11-07 10:57:40.000000', NULL, 1),
(6900702, 1039927, 69034, '<td valign="top">Nice take on the challenge.  : )</td>', 'Nice take on the challenge.  : )', '2012-11-07 11:22:11.000000', NULL, 1),
