(6901944, 1039967, 15711, '<td valign="top">This is so wonderfully simple!! 10 How appropriate, my 55,000th comment!</td>', 'This is so wonderfully simple!! 10 How appropriate, my 55,000th comment!', '2012-11-08 09:05:33.000000', NULL, 1),
(6902082, 1039954, 63218, '<td valign="top">At first, I thought it was a television reflecting the window behind it. Then I saw the chair &amp; realized it was a window. I like the wind. I don''t understand the title, though.</td>', 'At first, I thought it was a television reflecting the window behind it. Then I saw the chair & realized it was a window. I like the wind. I don''t understand the title, though.', '2012-11-08 13:00:25.000000', NULL, 1),
(6902092, 1039150, 63218, '<td valign="top">There''s an ambiguous logic to this that keeps me searching for more. I''m expecting to see ghosts.</td>', 'There''s an ambiguous logic to this that keeps me searching for more. I''m expecting to see ghosts.', '2012-11-08 13:18:58.000000', NULL, 1),
(6902097, 1039944, 63218, '<td valign="top">"D The crowd goes crazy! Huzzah!</td>', '"D The crowd goes crazy! Huzzah!', '2012-11-08 13:27:05.000000', NULL, 1),
